class ApplicationEngine {
    private String appName;
    private boolean running;

    public ApplicationEngine(String name) {
        this.appName = name;
        this.running = false;
    }

    public void start() {
        this.running = true;
        System.out.println(appName + " engine is now RUNNING in instance memory.");
    }

    public void stop() {
        this.running = false;
        System.out.println(appName + " engine stopped.");
    }
}

public class Main {
    // Static JVM Entry Point
    public static void main(String[] args) {
        System.out.println("[JVM] Entering static main() entry point...");

        // The idiomatic pattern: Bootstrap into Object-Oriented world!
        ApplicationEngine engine = new ApplicationEngine("FinTech-Core");
        engine.start();
        engine.stop();

        System.out.println("[JVM] Exiting main(). Application terminated cleanly.");
    }
}

