public class ArgumentParser {
    public static void main(String[] args) {
        System.out.println("Total CLI arguments passed: " + args.length);

        if (args.length == 0) {
            System.out.println("No arguments provided. Running in DEFAULT mode.");
        } else {
            for (int i = 0; i < args.length; i++) {
                System.out.println("Argument [" + i + "]: " + args[i]);
            }
        }
    }
}

