class CliSimulator {
    public static void processArgs(String[] args) {
        if (args == null || args.length == 0) {
            System.out.println("Default profile loaded");
        } else {
            System.out.println("Loaded " + args.length + " custom flags");
        }
    }
}

public class Main {
    public static void main(String[] args) {
        String[] simulatedArgs = {"--port=8080", "--debug"};
        CliSimulator.processArgs(simulatedArgs);
    }
}

